import com.androidhit.lumadrift.engine.*;
import java.nio.file.*;
import java.util.*;

/** Content acceptance uses an independent all-branch oracle, never just a stored solution. */
public final class LearningV114Test {
    static long checks,states,edges;
    static void check(boolean ok,String detail){checks++;if(!ok)throw new AssertionError(detail);}
    static void invalid(Runnable action){try{action.run();throw new AssertionError("Expected rejection");}catch(IllegalArgumentException expected){checks++;}}
    static int switches(Level level){int count=0;for(Tile tile:level.tiles)if(tile.switchMask!=0)count++;return count;}
    static void walk(Board board,AuditJourneyV114.Costs oracle,BitSet visited){int key=(int)((board.remainingMask()<<4)|board.gateMask());if(visited.get(key))return;visited.set(key);states++;long mask=board.remainingMask();int gates=board.gateMask();check(board.minimumActionsToFinish()==oracle.min(mask,gates),"Independent minimum at every intro state");check(board.hasSolution()&&!board.isDeadEnd(),"Every reached intro state remains logically solvable");
        for(int action:oracle.actions(mask,gates,0)){check(board.previewAction(action).legal,"Independent legal action agrees with preview");check(board.performAction(action).success,"Independent legal action is executable");edges++;walk(board,oracle,visited);check(board.undo()&&board.remainingMask()==mask&&board.gateMask()==gates,"Exit/open undo restores physical state");}
        for(Tile tile:board.level.tiles)check(board.canMove(tile.id)==(oracle.spatial(mask,tile)&&(gates&tile.direction.bit)!=0),"Every tile agrees with independent obstruction+gate model");
    }
    static void identicalGeometry(Level fresh,Level original){check(fresh.size==original.size&&fresh.tiles.size()==original.tiles.size()&&fresh.barriers.size()==original.barriers.size(),"Reordered physical bounds exact");check((fresh.initialGateMask|original.initialGateMask)==fresh.initialGateMask,"Initial N gates are an opening-only superset of L");for(Tile tile:fresh.tiles){Tile old=original.tile(tile.id);check(tile.row==old.row&&tile.col==old.col&&tile.direction==old.direction&&tile.switchMask==old.switchMask,"Reordered tile exact");}for(int i=0;i<fresh.barriers.size();i++){Barrier b=fresh.barriers.get(i),old=original.barriers.get(i);check(b.row==old.row&&b.col==old.col&&b.keyTileId==old.keyTileId,"Reordered seal association exact");}Board reachable=new Board(original);for(Direction direction:Direction.values())if((fresh.initialGateMask&~original.initialGateMask&direction.bit)!=0)check(reachable.performAction(Board.gateAction(direction)).success,"Each newly open gate is a legal old-L action");check(reachable.remainingMask()==fresh.allTilesMask&&reachable.gateMask()==fresh.initialGateMask,"New initial state reachable in original L without moving pieces");check(reachable.minimumActionsToFinish()==fresh.minimumActions,"Reauthored minimum agrees in exact preserved physical state");}
    static int expectedHard(int first){return first==31?0:first<=60?1:first<=100?2:first<=200?3:first<=400?4:first<=600?5:first<=800?6:7;}
    static List<String> layoutRows(Path source)throws Exception{List<String> rows=new ArrayList<>();for(String line:Files.readAllLines(source))if(line.trim().startsWith("\""))rows.add(line.trim());return rows;}
    static void independentMetrics(Level level,ProgressionInfo info,AuditJourneyV114.Costs oracle){long mask=level.allTilesMask;int gates=level.initialGateMask,decisions=0,forced=0,penalty=0,maxDepth=0;int[] depth=new int[level.tiles.size()];for(int action:level.actionSolution){int optimum=oracle.min(mask,gates),optimal=0,maxCost=optimum;int[] choices=oracle.actions(mask,gates,1);for(int choice:choices){long next=mask;int nextGates=gates;if(Board.isGateAction(choice))nextGates|=Board.gateDirection(choice).bit;else{next&=~(1L<<choice);nextGates^=level.tile(choice).switchMask;}int cost=1+oracle.min(next,nextGates);if(cost==optimum)optimal++;maxCost=Math.max(maxCost,cost);}if(choices.length>1&&maxCost>optimum)decisions++;if(optimal==1)forced++;penalty=Math.max(penalty,maxCost-optimum);if(Board.isGateAction(action))gates|=Board.gateDirection(action).bit;else{int value=1;for(int id=0;id<depth.length;id++)if((oracle.obstruction[action]&(1L<<id))!=0)value=Math.max(value,1+depth[id]);depth[action]=value;maxDepth=Math.max(maxDepth,value);mask&=~(1L<<action);gates^=level.tile(action).switchMask;}}
        check(info.decisionPoints==decisions&&info.forcedOptimalActions==forced&&info.maxOneChoicePenalty==penalty&&info.dependencyDepth==maxDepth,"Published choice/dependency metrics independently recalculated N"+level.number);int score=(int)Math.round(100.0*decisions/level.minimumActions)+3*(level.minimumActions-level.tiles.size())+2*info.keyCount+2*penalty+maxDepth;check(info.structuralScore==score,"Published structural score independently recalculated N"+level.number);}
    static double median(int first,int last,boolean decisions){int[] values=new int[last-first+1];for(int n=first;n<=last;n++)values[n-first]=decisions?LearningCatalog.info(n).decisionPoints:LearningCatalog.info(n).structuralScore;Arrays.sort(values);return(values[(values.length-1)/2]+values[values.length/2])/2.0;}
    public static void main(String[]args)throws Exception{Path out=Paths.get(args.length>0?args[0]:"docs/validation/v1.14/audit-learning");Files.createDirectories(out);Set<String> unique=new HashSet<>();Set<Integer> sources=new HashSet<>();int previousScore=0,maxRise=0,hard=0,expert=0,peaks=0,recoveries=0,meaningful=0,maxPieceIncrease=0,maxActionIncrease=0,previousPieces=2,previousMin=2;long gateStates=0;StringBuilder csv=new StringBuilder("level,minimum,goal,maximum_all_legal,maximum_immediately_useful,maximum_exits_first,independent_gate_states\n");
        for(int n=1;n<=LearningCatalog.LEVEL_COUNT;n++){Level level=LearningCatalog.get(n);ProgressionInfo info=LearningCatalog.info(n);check(level.progressionVersion==5&&info.version==5,"N version5");check(info.sourceFamily.equals(n<=30?"N":"L")&&info.sourceNumber==LearningCatalog.sourceNumber(n),"Provenance distinguishes authored N introductions and old L physical sources");check(unique.add(ProgressionAnalysis.canonical(level)),"N board unique under D4/translation/reorderedIDs: "+n);check(info.minimumActions==level.minimumActions&&info.mistakeAllowance==LearningCatalog.allowance(n),"Published preview data exact");check(level.tiles.size()<=20&&level.size<=7,"Finite solver bounds");for(Tile tile:level.tiles)check(Integer.bitCount(tile.switchMask)<=1,"No unintroduced dual-mask switches");
            if(n<=30){String expected=n<=4?"exits":n<=8?"blockers":n<=12?"key":n<=16?"gate":n<=20?"switch":n<=24?"switch_order":n<=27?"key_switch":"combination";check(LearningCatalog.lesson(n).equals(expected),"Explicit lesson phase");check(level.size==(n<=4?4:5),"Small intro grid");check(level.tiles.size()<=10,"Bounded intro density");check(switches(level)<=(n<=16?0:n<=20?1:n<=27?2:3),"Bounded intro switch count");check(info.keyCount<=(n>=9&&n<=12||n>=25?1:0),"No early key mixture");if(n<=12)check(level.initialGateMask==15&&info.requiredGateOpens==0,"No manual gate before own lesson");if(n>=13&&n<=16)check(info.requiredGateOpens==1&&switches(level)==0&&level.barriers.isEmpty(),"One isolated gate mechanic");if(n>=17&&n<=20)check(info.keyCount==0&&switches(level)==1,"One isolated switch mechanic");
                AuditJourneyV114.Costs oracle=new AuditJourneyV114.Costs(level);walk(new Board(level),oracle,new BitSet());}
            else{int source=LearningCatalog.sourceNumber(n);check(source>=31&&source<=1000&&sources.add(source),"970 distinct preserved source geometries");identicalGeometry(level,StrategyCatalog.get(source));int sizeCap=n<=60?5:n<=400?6:7,pieceCap=n<=60?13:n<=100?15:n<=160?17:n<=240?19:20,switchCap=n<=60?4:n<=100?5:n<=160?6:n<=240?7:9,keyCap=n<=160?1:2,sealCap=n<=400?2:3,minCap=n<=60?18:n<=100?20:n<=160?23:n<=240?26:28,depthCap=n<=160?9:13;
                check(level.size<=sizeCap&&level.tiles.size()<=pieceCap&&switches(level)<=switchCap&&info.keyCount<=keyCap&&level.barriers.size()<=sealCap&&level.minimumActions<=minCap&&info.dependencyDepth<=depthCap,"All nondecreasing mechanical phase caps hold N"+n);check(info.structuralScore-previousScore<=35,"No positive structural jump above35 after intro");check(level.tiles.size()-previousPieces<=2,"No positive piece jump above2 after intro");check(level.minimumActions-previousMin<=4,"No positive minimum-action jump above4 after intro");ProgressionInfo previous=LearningCatalog.info(n-1);check(info.requiredGateOpens-previous.requiredGateOpens<=2,"No positive required-opening jump above2 after intro");check(info.difficulty==(info.structuralScore>=110?ProgressionInfo.Difficulty.EXPERT:info.structuralScore>=80?ProgressionInfo.Difficulty.HARD:ProgressionInfo.Difficulty.NORMAL),"Labels follow actual recalculated score, never reassigned");if(info.difficulty==ProgressionInfo.Difficulty.EXPERT)check(n>400,"Expert reserved after400");if(n==31)check(new Board(level).legalMoves().size()>0&&info.requiredGateOpens<=1&&level.tiles.size()<=12&&info.structuralScore<=50,"N31 bridges intro with immediate exit and at most one opening");if(n==32)check(info.requiredGateOpens<=2,"N32 gradual openings");if(n==33)check(info.requiredGateOpens<=3,"N33 gradual openings");}
            AuditJourneyV114.Costs oracle=new AuditJourneyV114.Costs(level);int minimum=oracle.min(level.allTilesMask,level.initialGateMask);check(minimum==level.minimumActions,"Independent exact initial minimum, all1000");independentMetrics(level,info,oracle);gateStates+=(oracle.masks+1)*16;int a=oracle.maximum(level.allTilesMask,level.initialGateMask,0),u=oracle.maximum(level.allTilesMask,level.initialGateMask,1),g=oracle.maximum(level.allTilesMask,level.initialGateMask,2);check(a>=u&&u>=g&&g>=minimum,"Nested legal policy bounds");int budget=level.minimumActions+LearningCatalog.allowance(n);csv.append(n).append(',').append(minimum).append(',').append(budget).append(',').append(a).append(',').append(u).append(',').append(g).append(',').append((oracle.masks+1)*16).append('\n');
            Board board=new Board(level);for(int action:level.actionSolution)check(board.performAction(action).success,"Stored plan obeys actual N engine");check(board.isSolved()&&board.moves()==minimum,"Stored plan has independent exact length");Board restored=new Board(level);check(restored.restoreHistory(board.history())&&restored.isSolved(),"N typed history roundtrip");check(!restored.restoreHistory(new int[]{Integer.MAX_VALUE})&&restored.isSolved(),"Malformed N history rejected atomically");
            maxRise=Math.max(maxRise,info.structuralScore-previousScore);maxPieceIncrease=Math.max(maxPieceIncrease,level.tiles.size()-previousPieces);maxActionIncrease=Math.max(maxActionIncrease,minimum-previousMin);previousScore=info.structuralScore;previousPieces=level.tiles.size();previousMin=minimum;if(info.difficulty==ProgressionInfo.Difficulty.HARD)hard++;if(info.difficulty==ProgressionInfo.Difficulty.EXPERT)expert++;if(info.beat==ProgressionInfo.Beat.PEAK)peaks++;if(info.beat==ProgressionInfo.Beat.RECOVERY)recoveries++;if(info.decisionPoints>0)meaningful++;
        }
        check(sources.size()==970,"All970 sources present");invalid(()->LearningCatalog.get(0));invalid(()->LearningCatalog.get(1001));invalid(()->LearningCatalog.info(10,true));check(LearningCatalog.get(15).minimumActions==6&&LearningCatalog.get(15).tiles.size()==5&&switches(LearningCatalog.get(15))==0&&LearningCatalog.get(15).barriers.isEmpty(),"N15 isolates manual gate");
        int free=0,reauthored=0,run=0,maxRun=0;for(int n=1;n<=1000;n++){Level l=LearningCatalog.get(n);if(!new Board(l).legalMoves().isEmpty())free++;if(n>30&&l.initialGateMask!=StrategyCatalog.get(LearningCatalog.sourceNumber(n)).initialGateMask)reauthored++;if(LearningCatalog.info(n).difficulty!=ProgressionInfo.Difficulty.NORMAL){run++;maxRun=Math.max(run,maxRun);}else run=0;}check(free>=250&&free<=400,"25–40 percent of all initial states allow exits");check(maxRun<=4,"At most four consecutive actual Hard/Expert boards");check(hard==442&&expert==38,"Original actual Hard/Expert pool preserved without relabeling");
        for(int first=31;first<=1000;first+=10){int challenges=0,open=0;for(int n=first;n<first+10;n++){if(LearningCatalog.info(n).difficulty!=ProgressionInfo.Difficulty.NORMAL)challenges++;if(!new Board(LearningCatalog.get(n)).legalMoves().isEmpty())open++;}check(challenges==expectedHard(first),"Every episode follows its increasing challenge quota");check(open==3,"Every episode has three initial free-exit states");check(10-challenges>=3,"Every episode preserves at least three Normal boards, including late game");if(first>31){ProgressionInfo peak=LearningCatalog.info(first+8),recovery=LearningCatalog.info(first+9);check(peak.difficulty!=ProgressionInfo.Difficulty.NORMAL&&recovery.difficulty==ProgressionInfo.Difficulty.NORMAL&&recovery.structuralScore<peak.structuralScore*.8&&recovery.beat==ProgressionInfo.Beat.RECOVERY,"Every episode peak is followed by a genuine measured recovery");}}
        double previousMedian=-1,previousDecisionMedian=-1;for(int first=1;first<=1000;first+=200){double scoreMedian=median(first,first+199,false),decisionMedian=median(first,first+199,true);check(scoreMedian>=previousMedian&&decisionMedian>=previousDecisionMedian,"Structural and decision medians rise by 200-board tier");previousMedian=scoreMedian;previousDecisionMedian=decisionMedian;}
        if(args.length>1){Path root=Paths.get(args[1]);List<String> original=layoutRows(root.resolve("docs/validation/v1.14/audit-learning-rc1/LearningLayouts.java")),current=layoutRows(root.resolve("app/src/main/java/com/androidhit/lumadrift/engine/LearningLayouts.java"));check(original.size()==1000&&current.size()==1000,"Complete RC1 source retained");for(int i=0;i<30;i++)check(original.get(i).equals(current.get(i)),"First30 authored rows byte-identical to archived RC1");}
        Files.writeString(out.resolve("audit-learning-branches.csv"),csv);String report="{\n  \"passed\":true,\n  \"scope\":\"RC2:1000 N boards; exact independent branch bounds and choice metrics; exhaustive runtime first30;970 exact physical bases with opening-only initial supersets of preserved V4; not human comprehension, win rate or enjoyment\",\n  \"checks\":"+checks+",\n  \"boards\":1000,\n  \"uniqueUnderD4TranslationAndIds\":1000,\n  \"preservedGeometrySources\":970,\n  \"reauthoredInitialGateStates\":"+reauthored+",\n  \"initialStatesWithFreeExit\":"+free+",\n  \"maximumHardExpertRun\":"+maxRun+",\n  \"episodesWithThreeOrMoreNormals\":97,\n  \"independentGateStates\":"+gateStates+",\n  \"introRuntimeStates\":"+states+",\n  \"introRuntimeTransitions\":"+edges+",\n  \"meaningfulChoiceBoards\":"+meaningful+",\n  \"hardBoards\":"+hard+",\n  \"expertBoards\":"+expert+",\n  \"peaks\":"+peaks+",\n  \"recoveries\":"+recoveries+",\n  \"maximumPositiveScoreStep\":"+maxRise+",\n  \"maximumPieceIncrease\":"+maxPieceIncrease+",\n  \"maximumMinimumActionIncrease\":"+maxActionIncrease+"\n}\n";Files.writeString(out.resolve("audit-learning-contracts.json"),report);System.out.println(report);
    }
}
